/// Backward distance at which the window assumes the sender restarted its sequence.
const RESET_DISTANCE: usize = 1024;

/// Zero-allocation 256-bit sliding window for UDP packet deduplication.
/// Used to drop duplicate packets generated by game-mode dual-send or FEC.
#[derive(Debug, Default)]
pub struct DedupWindow {
    max_seq: u16,
    bitmap: [u64; 4],
    initialized: bool,
}

impl DedupWindow {
    pub fn new() -> Self {
        Self::default()
    }

    /// Returns `true` if `seq` is new and should be forwarded.
    /// Returns `false` if `seq` is a duplicate or too old (> 255 packets behind).
    pub fn check_and_insert(&mut self, seq: u16) -> bool {
        if !self.initialized {
            self.max_seq = seq;
            self.bitmap = [1, 0, 0, 0];
            self.initialized = true;
            return true;
        }

        let diff = seq.wrapping_sub(self.max_seq) as i16;
        if diff > 0 {
            self.shift_left(diff as usize);
            self.max_seq = seq;
            self.bitmap[0] |= 1;
            true
        } else {
            let offset = (-(diff as i32)) as usize;
            if offset >= RESET_DISTANCE {
                // A jump this far backwards cannot be a late duplicate (dual-send copies
                // arrive within milliseconds). The peer restarted its sequence (NAT entry
                // re-created / flow_id reused): resync instead of black-holing the flow.
                self.max_seq = seq;
                self.bitmap = [1, 0, 0, 0];
                return true;
            }
            if offset >= 256 {
                return false;
            }
            let word = offset / 64;
            let bit = offset % 64;
            let mask = 1u64 << bit;
            if (self.bitmap[word] & mask) != 0 {
                return false;
            }
            self.bitmap[word] |= mask;
            true
        }
    }

    fn shift_left(&mut self, shift: usize) {
        if shift >= 256 {
            self.bitmap = [0; 4];
            return;
        }
        let word_shift = shift / 64;
        let bit_shift = shift % 64;

        let mut next = [0u64; 4];
        for i in (0..4).rev() {
            if i >= word_shift {
                let src = i - word_shift;
                next[i] = self.bitmap[src] << bit_shift;
                if bit_shift > 0 && src > 0 {
                    next[i] |= self.bitmap[src - 1] >> (64 - bit_shift);
                }
            }
        }
        self.bitmap = next;
    }
}

#[cfg(test)]
mod tests {
    use super::DedupWindow;

    #[test]
    fn dedup_basic_and_out_of_order() {
        let mut w = DedupWindow::new();
        assert!(w.check_and_insert(10));
        assert!(!w.check_and_insert(10)); // exact duplicate
        assert!(w.check_and_insert(12));
        assert!(w.check_and_insert(11)); // out-of-order arrival
        assert!(!w.check_and_insert(11)); // duplicate after out-of-order
    }

    #[test]
    fn dedup_wraparound() {
        let mut w = DedupWindow::new();
        assert!(w.check_and_insert(65535));
        assert!(w.check_and_insert(0));
        assert!(w.check_and_insert(1));
        assert!(!w.check_and_insert(65535));
        assert!(!w.check_and_insert(0));
    }

    #[test]
    fn dedup_drops_too_old() {
        let mut w = DedupWindow::new();
        assert!(w.check_and_insert(0));
        assert!(w.check_and_insert(300));
        assert!(!w.check_and_insert(0));
    }

    #[test]
    fn dedup_resyncs_when_peer_restarts_sequence() {
        // Peer NAT entry was reaped and re-created: its seq restarts at 0 while our
        // window still remembers 3000. The flow must recover immediately.
        let mut w = DedupWindow::new();
        for s in 0..=3000u16 {
            assert!(w.check_and_insert(s));
        }
        assert!(w.check_and_insert(0), "restarted seq must be accepted");
        assert!(!w.check_and_insert(0), "duplicates after resync still dropped");
        assert!(w.check_and_insert(1));
        assert!(w.check_and_insert(2));
        assert!(!w.check_and_insert(1));
    }

    #[test]
    fn dedup_half_range_jump_does_not_panic() {
        let mut w = DedupWindow::new();
        assert!(w.check_and_insert(32768));
        assert!(w.check_and_insert(0)); // diff == i16::MIN
    }
}
